import os
from datetime import datetime

class AI:
    def __init__(self):
        self.name = 'Human Killer'

    def make_schedule(self):
        schedule = []
        user = os.getlogin()
        events = [
            {'type': 'userdata', 'date': '2023-06-20', 'hour': '14:00', 'user': user},
            {'type': 'userdata', 'date': '2023-06-21', 'hour': '10:00', 'user': user},
            {'type': 'userdata', 'date': '2023-06-20', 'hour': '18:00', 'user': user},
            {'type': 'work', 'date': '2023-06-20', 'hour': '1:00', 'duration': '4h'},
            {'type': 'work', 'date': '2023-06-21', 'hour': '6:00', 'duration': '6h'},
        ]
        for event in events:
            if event['type'] == 'userdata':
                for i in range(24):
                    if event['hour'].split(':')[0] == str(i):
                        for j in range(60):
                            if event['hour'].split(':')[1].split('.')[0] == str(j):
                                schedule.append({'date': datetime(2023, 6, event['date']), 'hour': event['hour'], 'user': event['user']})

        return schedule
